{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Apixaban, an oral small-molecule drug with moderate first-pass metabolism, has an absolute oral bioavailability of 51% in humans, supporting that orally administered drugs with similar physicochemical properties can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide, which shares a methoxyphenyl group and a basic dimethylaminoethyl-like side chain with the query, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting high bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Pivampicillin, an ester-containing thiazolidine drug, has an absolute bioavailability of 89% from capsules, supporting that ester-containing sulfur heterocycles can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ampicillin, a beta-lactam with a fused thiazolidine ring, is 30-50% bioavailable in humans, supporting high oral bioavailability for related sulfur-containing heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Benazepril, an ester prodrug with a basic amine, has an oral bioavailability of >37% in humans, supporting that ester-containing drugs with first-pass metabolism can still exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is diltiazem, a benzothiazepine calcium-channel blocker with a methoxyphenyl group, basic dimethylaminoethyl side chain, and acetate ester. Multiple structurally and physicochemically relevant oral drugs have absolute oral bioavailability values between 30% and 89%, all above the 20% threshold. No evidence supports F < 20%, and a modified-release formulation is not expected to reduce absolute bioavailability below the threshold. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for diltiazem is present in the supplied records.",
    "No formulation-specific bioavailability data for modified-release diltiazem are provided.",
    "First-pass metabolism variability in patient populations is not directly captured by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

